<?php
require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){madin_csrf_check();$id=(int)($_POST['id_pesanan']??0);$status=(string)($_POST['status_pesanan']??'');$bayar=(string)($_POST['status_pembayaran']??'');$allowedStatus=['menunggu','diproses','siap_diambil','dikirim','selesai','dibatalkan'];$allowedBayar=['menunggu','berhasil','gagal','dikembalikan'];if($id<1||!in_array($status,$allowedStatus,true)||!in_array($bayar,$allowedBayar,true))$error='Status pesanan tidak valid.';else{$stmt=mysqli_prepare($conn,'UPDATE pesanan SET status_pesanan=?,status_pembayaran=? WHERE id_pesanan=?');mysqli_stmt_bind_param($stmt,'ssi',$status,$bayar,$id);$ok=mysqli_stmt_execute($stmt);$err=mysqli_stmt_error($stmt);mysqli_stmt_close($stmt);if($ok){header('Location: pesanan.php?msg='.rawurlencode('Status pesanan berhasil diperbarui.'));exit;}else $error='Gagal memperbarui pesanan: '.$err;}}
$q=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'');$search='%'.$q.'%';$sql="SELECT * FROM pesanan WHERE (kode_pesanan LIKE ? OR nama_pelanggan LIKE ?)";$types='ss';$params=[$search,$search];if(in_array($statusFilter,['menunggu','diproses','siap_diambil','dikirim','selesai','dibatalkan'],true)){$sql.=' AND status_pesanan=?';$types.='s';$params[]=$statusFilter;}$sql.=' ORDER BY dibuat_pada DESC LIMIT 250';$stmt=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($stmt,$types,...$params);mysqli_stmt_execute($stmt);$orders=mysqli_stmt_get_result($stmt);madin_admin_header('Manajemen Pesanan','pesanan');if($error):?><div class="notice error"><?=madin_e($error)?></div><?php endif;?>
<div class="admin-card"><h2>Daftar pesanan</h2><form class="filter-row" method="get"><input name="q" placeholder="Cari kode atau nama pelanggan" value="<?=madin_e($q)?>"><select name="status"><option value="">Semua status</option><?php foreach(['menunggu','diproses','siap_diambil','dikirim','selesai','dibatalkan'] as $st):?><option value="<?=$st?>" <?=$statusFilter===$st?'selected':''?>><?=madin_e(madin_status_label($st))?></option><?php endforeach;?></select><button class="btn">Filter</button><a class="btn secondary" href="pesanan.php">Reset</a></form><table class="admin-table"><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Total</th><th>Metode</th><th>Status pesanan & pembayaran</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php if($orders&&mysqli_num_rows($orders)):while($o=mysqli_fetch_assoc($orders)):?><tr><td><strong><?=madin_e($o['kode_pesanan'])?></strong><br><small>#<?=$o['id_pesanan']?></small></td><td><?=madin_e($o['nama_pelanggan'])?><br><small><?=madin_e($o['telepon_pelanggan']??'')?></small></td><td><?=madin_money($o['total'])?></td><td><?=madin_e(strtoupper($o['metode_pembayaran']))?></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf_token" value="<?=madin_e(madin_csrf_token())?>"><input type="hidden" name="id_pesanan" value="<?=$o['id_pesanan']?>"><div><select name="status_pesanan" aria-label="Status pesanan"><?php foreach(['menunggu','diproses','siap_diambil','dikirim','selesai','dibatalkan'] as $st):?><option value="<?=$st?>" <?=$o['status_pesanan']===$st?'selected':''?>><?=madin_e(madin_status_label($st))?></option><?php endforeach;?></select><select name="status_pembayaran" aria-label="Status pembayaran" style="margin-top:5px"><?php foreach(['menunggu','berhasil','gagal','dikembalikan'] as $st):?><option value="<?=$st?>" <?=$o['status_pembayaran']===$st?'selected':''?>>Bayar: <?=madin_e(madin_status_label($st))?></option><?php endforeach;?></select></div><button class="btn-small">Simpan</button></form></td><td><?=madin_e(date('d/m/Y H:i',strtotime($o['dibuat_pada'])))?></td><td><a class="btn-small secondary" href="pesanan_detail.php?id=<?=$o['id_pesanan']?>">Detail</a></td></tr><?php endwhile;else:?><tr><td colspan="7" class="empty-state">Tidak ada pesanan yang cocok.</td></tr><?php endif;?></tbody></table></div><?php mysqli_stmt_close($stmt);madin_admin_footer(); ?>
